-- PD-ARCH-01G-B refinement: original brand layers and logical deletion of design proposals. Additive only.
--
-- A proposal is now composed locally: the bitmap generated by the provider is kept as its own file (the background,
-- never sent with a protected asset in it) and the official logo, the mascot or another reserved brand asset is placed
-- over it unchanged, in a fixed zone that the prompt keeps empty. `file_path` is the composed preview;
-- `background_file_path` and `background_sha256` are the generated bitmap; `layers_json` lists the placed assets and
-- their pixel boxes (the data a structured template of PD-ARCH-01G-C needs). Proposals saved before this migration have
-- no separate background: their file is the generated bitmap.
--
-- `deleted_at` hides a proposal the operator discards; the row, its decisions and its files are kept (OD-08).
ALTER TABLE design_proposals ADD COLUMN background_file_path TEXT NULL;
ALTER TABLE design_proposals ADD COLUMN background_sha256 TEXT NULL
  CHECK (background_sha256 IS NULL OR length(background_sha256) = 64);
ALTER TABLE design_proposals ADD COLUMN layers_json TEXT NULL
  CHECK (layers_json IS NULL OR (json_valid(layers_json) AND json_type(layers_json) = 'array'));
ALTER TABLE design_proposals ADD COLUMN deleted_at TEXT NULL;
